6:/** A grade's rate on the sheet: a percent as two-decimal text, in force from its from-date
7: *  (yyyy-MM-dd; null applies from the beginning of time) through its to-date (null: no end). A grade
8: *  with no rate is not listed. Its level is how far up the sheet's parent chain it comes from (0: the
9: *  sheet's own; 1: its parent's; up to 3). Its version is how many versions the grade's rate from that
10: *  from-date has had: setting it again keeps the old value as an older version; this, the newest, is in force. */
11:export type Rate = {
12:  sheetId: string; grade: string; pct: string; from: string | null; to: string | null; level: number; version: number;
13:};
14:/** A blank `from` sets the rate that applies from the beginning of time; a blank `to` has no end. */
15:export type RateInput = { grade: string; pct: string; from: string; to: string };
