21:/** The sheet's own rates, by grade, then by from-date (none first), then those it inherits from its
22: *  parent chain, each at its level. */
23:export function listRates(sheetId: string, live = false): Promise<Rate[]> {
24:  return getJson<Rate[]>(base(sheetId), live);
25:}
26:
27:/** Set a grade's rate from a from-date, as a new version of the one with the same grade and from-date;
28: *  refused (rejects) when the percent is missing, negative or has more than two decimals, or the
29: *  from-date or to-date is not a date, or the to-date is before the from-date. */
30:export function setRate(sheetId: string, by: string, input: RateInput): Promise<Rate> {
31:  return postJson<Rate>(`${base(sheetId)}?by=${encodeURIComponent(by)}`, input);
32:}
33:
34:/** How many rates an import set. */
35:export type ImportRatesResult = { set: number };
36:
37:/** Set a rate per line of grade,rate,from,to (the from-date and to-date may be absent or blank), in
38: *  order, each as `setRate` sets it; refused (rejects) with nothing set when there is no line or any
39: *  line would be refused by `setRate`. */
40:export function importRates(sheetId: string, by: string, text: string): Promise<ImportRatesResult> {
41:  return postJson<ImportRatesResult>(`/api/sheets/${encodeURIComponent(sheetId)}/import-rates?by=${encodeURIComponent(by)}`, { text });
42:}
43:
44:/** The grade's rate in force on a date (yyyy-MM-dd): the one with the latest from-date on or
45: *  before it; at a level where the date is before every rate the grade has, or it has none, or
46: *  that one ended (its to-date) before the date, the next level up is looked at; undefined (n/a)
47: *  when no level has one. */
48:export function rateOn(rates: Rate[] | undefined, grade: string, date: string): string | undefined {
49:  const levels = [...new Set((rates ?? []).map((r) => r.level ?? 0))].sort((a, b) => a - b);
50:  for (const level of levels) {
51:    let found: Rate | undefined;
52:    for (const r of rates ?? []) {
53:      if ((r.level ?? 0) !== level || r.grade !== grade || (r.from !== null && r.from > date)) continue;
54:      if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
55:    }
56:    if (found !== undefined && (found.to === null || found.to >= date)) return found.pct;
57:  }
58:  return undefined;
59:}
60:
61:/** The rate in force on a date for each grade that has one then. */
62:export function rateByGrade(rates: Rate[] | undefined, date: string): Map<string, string> {
63:  const byGrade = new Map<string, string>();
64:  for (const r of rates ?? []) {
65:    const pct = rateOn(rates, r.grade, date);
66:    if (pct !== undefined) byGrade.set(r.grade, pct);
67:  }
68:  return byGrade;
69:}
