71:/** Two-decimal text (may be negative) as a whole number of hundredths. */
72:export function hundredths(text: string): bigint {
73:  const t = text.trim();
74:  const negative = t.startsWith('-');
75:  const [whole, frac = ''] = (negative ? t.slice(1) : t).split('.');
76:  const value = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
77:  return negative ? -value : value;
78:}
79:
80:/** A claim's rate figure: an amount times a percent, divided by 100, rounded to two decimals (half up
81: *  when `halfUp`, else half to even; no floor: that is applied last, by `claimDue`);
82: *  null (n/a) when there is no rate. Exact: worked in whole hundredths. */
83:export function dueOf(amount: string, pct: string | undefined, halfUp: boolean): string | null {
84:  if (pct === undefined) return null;
85:  // amount (1/100) x pct (1/100) / 100 is in 1/1_000_000; to cents is / 10_000.
86:  return formatCents(roundPct(hundredths(amount) * hundredths(pct), halfUp));
87:}
88:
89:/** What a claim's late charge goes by: the sheet's late percent by date (a charge goes by the one in force on each 30-day boundary) and its today (a claim's due-by is its own);
90: *  the sheet's policy date (its today when blank), which decides how a claim's live figures round; and the date
91: *  a claim's lateness counts from (`lateFrom`: its due-by plus the grace days of its person's grade in force on
92: *  its date, as in force on that date); and the rounding mode by date (half-up or half-even; '': none). */
93:export type Late = { pct: DatedOn; today: string; policy: string; lateFrom: (c: Claim) => string; rounding: DatedOn };
94:
95:/** Whether a claim's live figures round half up: by the rounding mode in force on its round date (its
96: *  own, or for a correction the date of the claim it corrects); with none, when that date is before the
97: *  policy date; else they round half to even. */
98:export const roundsHalfUp = (c: Claim, late: Late) => {
99:  const date = c.roundDate ?? c.date;
100:  const mode = late.rounding(date);
101:  return mode === 'half-up' ? true : mode === 'half-even' ? false : date < late.policy;
102:};
103:
104:/** The late charge on an open (OPEN or PENDING) claim's `figure`, compounding: for each full 30 days it is past its
105: *  due-by plus its grace days (`late.lateFrom`) on the sheet's today, the late percent in force on that boundary date
106: *  (that date plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries before it,
107: *  each rounded by the policy date to two decimals, added up (0 when not overdue, and on a correction). */
108:export function lateCharge(c: Claim, figure: string, late: Late): bigint {
109:  const from = late.lateFrom(c);
110:  if (isCorrection(c) || !isOverdue(c, late.today, from)) return 0n;
111:  const start = Date.parse(`${from}T00:00:00Z`);
112:  const periods = Math.floor((Date.parse(`${late.today}T00:00:00Z`) - start) / 86_400_000 / 30);
113:  let total = 0n;
114:  for (let k = 1; k <= periods; k++) {
115:    const boundary = new Date(start + k * 30 * 86_400_000).toISOString().slice(0, 10);
116:    total += roundPct((hundredths(figure) + total) * hundredths(late.pct(boundary)), roundsHalfUp(c, late));
117:  }
118:  return total;
119:}
120:
121:/** A person's grade in force on a date (yyyy-MM-dd). */
122:export type GradeOn = (date: string) => string;
123:
124:/** A claim's due: the one fixed when it was settled (its late charge then frozen in), else its
125: *  figure — the one bound by its person's last statement (not while PENDING; n/a when it bound none), else live at the rate in force on the
126: *  claim's date of the grade in force then (`gradeOn`) — with its late charge on the sheet's today on top, and
127: *  at least the `floor` in force on its date, applied last (a correction, a negative amount, has no floor). */
128:export function claimDue(c: Claim, rates: Rate[] | undefined, gradeOn: GradeOn, floor: DatedOn, late: Late): string | null {
129:  if (c.settledDue !== null) return c.settledDue;
130:  const figure = c.stated && c.status !== 'PENDING' ? c.statedDue : dueOf(c.amount, rateOn(rates, gradeOn(c.date), c.date), roundsHalfUp(c, late));
131:  if (figure === null) return null;
132:  const due = hundredths(figure) + lateCharge(c, figure, late);
133:  const least = hundredths(floor(c.date));
134:  return formatCents(!isCorrection(c) && due < least ? least : due);
135:}
136:
137:/** A product of hundredths and a percent's hundredths (in 1/1_000_000) to cents, half up (away
138: *  from zero) when `halfUp`, else half to even (symmetric about zero). */
139:function roundPct(product: bigint, halfUp: boolean): bigint {
140:  if (product < 0n) return -roundPct(-product, halfUp);
141:  const whole = product / 10_000n;
142:  const rest = product % 10_000n;
143:  return rest > 5_000n || (rest === 5_000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole;
144:}
145:
146:/** A person's due-total: the sum of their counting claims' due figures (n/a ones skipped), at
147: *  most the sheet's `cap` (null: no cap); n/a
148: *  when their grade today has no rate today (`pct`) and none of those claims keeps a settled or bound
149: *  figure, or a live one at a grade no longer in force on the sheet's today or dated on or before it
150: *  (its rate since ended). */
151:export function personDue(claims: Claim[], rates: Rate[] | undefined, gradeOn: GradeOn, pct: string | undefined,
152:  floor: DatedOn, late: Late, cap: string | null) {
153:  const own = claims.filter(counts);
154:  const now = gradeOn(late.today);
155:  const kept = (c: Claim) => c.settledDue !== null || isBound(c)
156:    || ((gradeOn(c.date) !== now || c.date <= late.today) && rateOn(rates, gradeOn(c.date), c.date) !== undefined);
157:  if (pct === undefined && !own.some(kept)) return null;
158:  const sum = sumDues(own.map((c) => claimDue(c, rates, gradeOn, floor, late)));
159:  return cap !== null && hundredths(sum) > hundredths(cap) ? formatCents(hundredths(cap)) : sum;
160:}
161:
162:/** What a person's due figures add up to above the sheet's `cap` (null: no cap); 0.00 when they do
163: *  not exceed it, or their due-total is n/a. */
164:export function excessOf(claims: Claim[], rates: Rate[] | undefined, gradeOn: GradeOn, pct: string | undefined,
165:  floor: DatedOn, late: Late, cap: string | null): string {
166:  const full = personDue(claims, rates, gradeOn, pct, floor, late, null);
167:  return full === null || cap === null || hundredths(full) <= hundredths(cap) ? '0.00'
168:    : formatCents(hundredths(full) - hundredths(cap));
169:}
170:
171:/** A person's due split by status among their claims that count (`claims`, the live ones): settled (their SETTLED
172: *  claims, at their frozen figures, corrections included) and open (their OPEN and PENDING ones); n/a ones skipped.
173: *  The two add up to their due-total before the cap. */
174:export function splitDues(claims: Claim[], dueOfClaim: (c: Claim) => string | null) {
175:  return {
176:    settled: sumDues(claims.filter((c) => c.status === 'SETTLED').map(dueOfClaim)),
177:    open: sumDues(claims.filter(isOpen).map(dueOfClaim)),
178:  };
179:}
180:
181:/** The overdue claims among those that count (`claims`, the live ones) on the sheet's today (`charges.today`,
182: *  each past its `charges.lateFrom`): their count and the sum of their due figures (n/a ones skipped). */
183:export function overdue(claims: Claim[], charges: Late, dueOfClaim: (c: Claim) => string | null) {
184:  const late = claims.filter((c) => isOverdue(c, charges.today, charges.lateFrom(c)));
185:  return { count: late.length, total: sumDues(late.map(dueOfClaim)) };
186:}
187:
188:/** The due of the open (OPEN or PENDING) claims among those that count (`claims`, the live ones), split by
189: *  their age on the sheet's `today` (the days from the claim's date): 0 to 30, 31 to 60, and 61 or more
190: *  (one dated after today is 0 to 30); n/a ones skipped. */
191:export function agedDues(claims: Claim[], today: string, dueOfClaim: (c: Claim) => string | null) {
192:  const buckets: Array<Array<string | null>> = [[], [], []];
193:  const now = Date.parse(`${today}T00:00:00Z`);
194:  for (const c of claims.filter(isOpen)) {
195:    const age = today === '' ? 0 : Math.round((now - Date.parse(`${c.date}T00:00:00Z`)) / 86_400_000);
196:    buckets[age <= 30 ? 0 : age <= 60 ? 1 : 2].push(dueOfClaim(c));
197:  }
198:  return { upTo30: sumDues(buckets[0]), upTo60: sumDues(buckets[1]), over60: sumDues(buckets[2]) };
199:}
200:
201:/** Add up two-decimal dues, skipping n/a. */
202:export function sumDues(dues: Array<string | null>): string {
203:  return formatCents(dues.reduce<bigint>((t, d) => (d === null ? t : t + hundredths(d)), 0n));
204:}
205:
206:/** A sheet total of per-person figures: added up (n/a ones are no figure), leaving out the single
207: *  highest and the single lowest figure when there are three or more. */
208:export function trimmedSum(figures: Array<string | null>): string {
209:  const cents = figures.filter((f): f is string => f !== null).map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
210:  const kept = cents.length >= 3 ? cents.slice(1, -1) : cents;
211:  return formatCents(kept.reduce((t, c) => t + c, 0n));
212:}
213:
214:export function formatCents(cents: bigint): string {
215:  const abs = cents < 0n ? -cents : cents;
216:  const frac = (abs % 100n).toString().padStart(2, '0');
217:  return `${cents < 0n ? '-' : ''}${abs / 100n}.${frac}`;
218:}
219:
220:/** A due as shown: n/a when there is none. */
221:export const showDue = (due: string | null) => due ?? 'n/a';
222:
223:/** What a candidate rate for a grade on every date would change: how many open (OPEN or PENDING) claims
224: *  of people on that grade on the claim's date would show a different due, and the sum of the differences
225: *  (new minus current, two decimals). */
226:export type RatePreview = { count: number; diff: string };
227:
228:/** Preview a candidate rate for a grade; nothing is saved. Refused (rejects) when the percent is missing,
229: *  negative or has more than two decimals. */
230:export function previewRate(sheetId: string, grade: string, pct: string): Promise<RatePreview> {
231:  return getJson<RatePreview>(`/api/sheets/${encodeURIComponent(sheetId)}/rate-preview`
232:    + `?grade=${encodeURIComponent(grade)}&pct=${encodeURIComponent(pct)}`);
233:}

