181:/** The overdue claims among those that count (`claims`, the live ones) on the sheet's today (`charges.today`,
182: *  each past its `charges.lateFrom`): their count and the sum of their due figures (n/a ones skipped). */
183:export function overdue(claims: Claim[], charges: Late, dueOfClaim: (c: Claim) => string | null) {
184:  const late = claims.filter((c) => isOverdue(c, charges.today, charges.lateFrom(c)));
185:  return { count: late.length, total: sumDues(late.map(dueOfClaim)) };
186:}
