188:/** The due of the open (OPEN or PENDING) claims among those that count (`claims`, the live ones), split by
189: *  their age on the sheet's `today` (the days from the claim's date): 0 to 30, 31 to 60, and 61 or more
190: *  (one dated after today is 0 to 30); n/a ones skipped. */
191:export function agedDues(claims: Claim[], today: string, dueOfClaim: (c: Claim) => string | null) {
192:  const buckets: Array<Array<string | null>> = [[], [], []];
193:  const now = Date.parse(`${today}T00:00:00Z`);
194:  for (const c of claims.filter(isOpen)) {
195:    const age = today === '' ? 0 : Math.round((now - Date.parse(`${c.date}T00:00:00Z`)) / 86_400_000);
