201:/** Add up two-decimal dues, skipping n/a. */
202:export function sumDues(dues: Array<string | null>): string {
203:  return formatCents(dues.reduce<bigint>((t, d) => (d === null ? t : t + hundredths(d)), 0n));
204:}
