206:/** A sheet total of per-person figures: added up (n/a ones are no figure), leaving out the single
207: *  highest and the single lowest figure when there are three or more. */
208:export function trimmedSum(figures: Array<string | null>): string {
209:  const cents = figures.filter((f): f is string => f !== null).map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
210:  const kept = cents.length >= 3 ? cents.slice(1, -1) : cents;
211:  return formatCents(kept.reduce((t, c) => t + c, 0n));
212:}
