214:export function formatCents(cents: bigint): string {
215:  const abs = cents < 0n ? -cents : cents;
216:  const frac = (abs % 100n).toString().padStart(2, '0');
217:  return `${cents < 0n ? '-' : ''}${abs / 100n}.${frac}`;
218:}
