220:/** A due as shown: n/a when there is none. */
221:export const showDue = (due: string | null) => due ?? 'n/a';
222:
223:/** What a candidate rate for a grade on every date would change: how many open (OPEN or PENDING) claims
224: *  of people on that grade on the claim's date would show a different due, and the sum of the differences
225: *  (new minus current, two decimals). */
226:export type RatePreview = { count: number; diff: string };
227:
228:/** Preview a candidate rate for a grade; nothing is saved. Refused (rejects) when the percent is missing,
229: *  negative or has more than two decimals. */
230:export function previewRate(sheetId: string, grade: string, pct: string): Promise<RatePreview> {
231:  return getJson<RatePreview>(`/api/sheets/${encodeURIComponent(sheetId)}/rate-preview`
232:    + `?grade=${encodeURIComponent(grade)}&pct=${encodeURIComponent(pct)}`);
233:}

